components.css:
.ds-tabs { display: flex; gap: 8px; flex-wrap: wrap; padding: 8px 0 28px; border-bottom: 1px solid #3A3145; }
.ds-tab { font-family: 'Geist Mono', monospace; font-size: 10.5px; letter-spacing: 0.09em; text-transform: uppercase; color: #B0A695; padding: 2px 8px 3px; border-radius: 999px; background: transparent; border: 1px solid #3A3145; cursor: pointer; transition: color 180ms cubic-bezier(0.16, 1, 0.3, 1), background 180ms cubic-bezier(0.16, 1, 0.3, 1), border-color 180ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-tab:hover { color: #F0E6D7; border-color: #221C29; }
.ds-tab-active { color: color-mix(in oklab, #E8A598 85%, #F0E6D7); background: color-mix(in oklab, #E8A598 9%, transparent); border-color: color-mix(in oklab, #E8A598 18%, transparent); }
.ds-tab:focus-visible { outline: 2px solid #E8A598; outline-offset: 2px; }

.ds-card-lg { display: block; padding: 16px; border: 1px solid #3A3145; background: #221C29; border-radius: 14px; text-decoration: none; transition: transform 380ms cubic-bezier(0.16, 1, 0.3, 1), box-shadow 380ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-card-lg:hover { transform: translateY(-4px); box-shadow: 0 14px 32px -16px color-mix(in oklab, #2D8E91 60%, transparent), 0 2px 8px -4px color-mix(in oklab, #2D8E91 30%, transparent); }
.ds-card-lg .ds-card-image { position: relative; aspect-ratio: 16 / 9; margin-bottom: 22px; border-radius: 10px; overflow: hidden; background: #2D2638; }
.ds-card-lg .ds-card-image img { width: 100%; height: 100%; object-fit: cover; transition: filter 320ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-card-lg:hover .ds-card-image img { filter: saturate(1.06) brightness(1.02); }
.ds-card-lg .ds-card-image::after { content: ''; position: absolute; inset: 0; border-radius: inherit; box-shadow: inset 0 0 0 1px color-mix(in oklab, #F0E6D7 5%, transparent); pointer-events: none; }
.ds-card-lg .ds-card-text { display: flex; flex-direction: column; gap: 14px; }
.ds-card-lg .ds-card-title { font-family: 'Geist', sans-serif; font-size: 30px; font-weight: 600; line-height: 1.2; letter-spacing: -0.012em; color: #F0E6D7; text-wrap: balance; margin: 0; }
.ds-card-lg .ds-card-excerpt { color: #B0A695; font-size: 16px; line-height: 1.55; margin: 0; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.ds-pill { display: inline-flex; align-items: center; align-self: flex-start; width: fit-content; font-family: 'Geist Mono', monospace; font-size: 10.5px; font-weight: 500; letter-spacing: 0.09em; text-transform: uppercase; padding: 2px 8px 3px; border-radius: 999px; background: color-mix(in oklab, #2D8E91 9%, transparent); color: color-mix(in oklab, #2D8E91 85%, #F0E6D7); border: 1px solid color-mix(in oklab, #2D8E91 18%, transparent); }

.ds-card-v { display: flex; flex-direction: column; gap: 18px; padding: 16px; border: 1px solid #3A3145; border-radius: 14px; background: #221C29; text-decoration: none; transition: transform 380ms cubic-bezier(0.16, 1, 0.3, 1), box-shadow 380ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-card-v:hover { transform: translateY(-4px); box-shadow: 0 14px 32px -16px color-mix(in oklab, #D9896E 60%, transparent), 0 2px 8px -4px color-mix(in oklab, #D9896E 30%, transparent); }
.ds-card-v .ds-card-image { position: relative; aspect-ratio: 16 / 9; border-radius: 10px; overflow: hidden; background: #2D2638; }
.ds-card-v .ds-card-image img { width: 100%; height: 100%; object-fit: cover; transition: filter 320ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-card-v:hover .ds-card-image img { filter: saturate(1.06) brightness(1.02); }
.ds-card-v .ds-card-text { display: flex; flex-direction: column; gap: 12px; }
.ds-card-v .ds-card-title { font-family: 'Geist', sans-serif; font-size: 20px; font-weight: 600; line-height: 1.22; letter-spacing: -0.012em; color: #F0E6D7; text-wrap: balance; margin: 0; }
.ds-pill-design { background: color-mix(in oklab, #D9896E 9%, transparent); color: color-mix(in oklab, #D9896E 85%, #F0E6D7); border-color: color-mix(in oklab, #D9896E 18%, transparent); }
.ds-pill { display: inline-flex; align-items: center; align-self: flex-start; width: fit-content; font-family: 'Geist Mono', monospace; font-size: 10.5px; font-weight: 500; letter-spacing: 0.09em; text-transform: uppercase; padding: 2px 8px 3px; border-radius: 999px; border: 1px solid; }

.ds-icon-btn { display: inline-flex; align-items: center; gap: 6px; color: #B0A695; background: transparent; border: none; padding: 8px; border-radius: 8px; cursor: pointer; transition: color 150ms cubic-bezier(0.16, 1, 0.3, 1), background 150ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-icon-btn:hover { color: #F0E6D7; background: color-mix(in oklab, #F0E6D7 6%, transparent); }
.ds-icon-btn:focus-visible { outline: 2px solid #E8A598; outline-offset: 2px; }
.ds-kbd { font-family: 'Geist Mono', monospace; font-size: 12px; color: #76695E; border: 1px solid #3A3145; border-radius: 5px; padding: 1px 5px 2px; }

.ds-sources { list-style: none; margin: 0; padding: 18px 0 0; display: flex; flex-direction: column; gap: 20px; border-top: 1px solid color-mix(in oklab, #2D8E91 50%, transparent); }
.ds-sources li { display: flex; flex-direction: column; gap: 4px; font-size: 14px; line-height: 1.4; }
.ds-source-num { color: #2D8E91; font-family: 'Geist Mono', monospace; font-size: 13px; letter-spacing: 0.02em; }
.ds-source-title { color: #F0E6D7; font-family: 'Geist', sans-serif; font-size: 14px; font-weight: 400; text-decoration: none; transition: color 200ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-source-title:hover { color: #5FB3B6; }
.ds-source-url { color: #76695E; font-family: 'Geist Mono', monospace; font-size: 12px; }
